use data::*;

macro_rules! implies {
  ($lhs: expr, $rhs: expr) => {
    !$lhs || $rhs
  };
}

macro_rules! impliesL {
  ($lhs: expr, $rhs: expr) => {
    !$lhs | $rhs
  };
}

/** Initialize EntryPointContract
  *
  * guarantee initOutputDataPort
  *   The Initialize Entry Point must initialize all component
  *   local state and all output data ports.
  * @param api_output outgoing data port
  */
pub fn initialize_initOutputDataPort(api_output: bool) -> bool
{
  api_output == false
}

/** IEP-Guar: Initialize Entrypoint for actuator
  *
  * @param api_output outgoing data port
  */
pub fn initialize_IEP_Guar(api_output: bool) -> bool
{
  initialize_initOutputDataPort(api_output)
}

/** IEP-Post: Initialize Entrypoint Post-Condition
  *
  * @param api_output outgoing data port
  */
pub fn initialize_IEP_Post(api_output: bool) -> bool
{
  initialize_IEP_Guar(api_output)
}

/** Compute Entrypoint Contract
  *
  * guarantee actuatorOutput
  * @param api_input incoming data port
  * @param api_manualActuatorInput incoming data port
  * @param api_output outgoing data port
  */
pub fn compute_spec_actuatorOutput_guarantee(
  api_input: bool,
  api_manualActuatorInput: bool,
  api_output: bool) -> bool
{
  api_output == api_input | api_manualActuatorInput
}

/** CEP-T-Guar: Top-level guarantee contracts for actuator's compute entrypoint
  *
  * @param api_input incoming data port
  * @param api_manualActuatorInput incoming data port
  * @param api_output outgoing data port
  */
pub fn compute_CEP_T_Guar(
  api_input: bool,
  api_manualActuatorInput: bool,
  api_output: bool) -> bool
{
  let r0: bool = compute_spec_actuatorOutput_guarantee(api_input, api_manualActuatorInput, api_output);

  return r0;
}

/** CEP-Post: Compute Entrypoint Post-Condition for actuator
  *
  * @param api_input incoming data port
  * @param api_manualActuatorInput incoming data port
  * @param api_output outgoing data port
  */
pub fn compute_CEP_Post(
  api_input: bool,
  api_manualActuatorInput: bool,
  api_output: bool) -> bool
{
  // CEP-Guar: guarantee clauses of actuator's compute entrypoint
  let r0: bool = compute_CEP_T_Guar(api_input, api_manualActuatorInput, api_output);

  return r0;
}
